quote=banner('Tell Us About Your Project.','Provide a few details about your construction requirements and our team can review your enquiry once delivery is configured.','during.jpg','REQUEST A QUOTE')+f'''<section class="section wrap quote-layout"><aside><p class="kicker gold">LET’S GET STARTED</p><h2>Every great build starts with a conversation.</h2><p>Share your plans, location and project requirements so your enquiry is ready when contact details are available.</p><div class="notice"><b>Please note</b><p>This form does not send enquiries yet. You can validate and download your completed brief; delivery requires a configured backend and verified company contact details.</p></div></aside><div class="form-panel"><form class="enquiry-form" data-kind="Project quotation enquiry"><fieldset><legend>01 <span>Client information</span></legend><div class="form-grid"><label>Full name *<input name="Full name" required autocomplete="name"></label><label>Email address *<input name="Email" type="email" required autocomplete="email"></label><label>Telephone number *<input name="Telephone" type="tel" required autocomplete="tel"></label><label>Preferred contact method *{select('Preferred contact method',['Email','Telephone'])}</label></div></fieldset><fieldset><legend>02 <span>Project information</span></legend><div class="form-grid"><label>Project name (optional)<input name="Project name"></label><label>Project type *{select('Project type',['Residential Construction','Commercial Construction','Industrial Construction','Renovations and Extensions','Swimming Pool Construction','Civil Works','Project Management','Other'])}</label><label class="wide">Project location *<input name="Project location" required></label><label class="wide">Project description *<textarea name="Project description" rows="5" required></textarea></label></div></fieldset><fieldset><legend>03 <span>Project budget</span></legend><label>Budget range *{select('Budget',['Under R50,000','R50,000 – R100,000','R100,000 – R250,000','R250,000 – R500,000','R500,000 – R1 million','Above R1 million','Not yet determined'])}</label></fieldset><fieldset><legend>04 <span>Project timeline</span></legend><label>When are you planning to start? *{select('Timeline',['Immediately','Within 1–3 months','Within 3–6 months','More than 6 months','Still planning'])}</label></fieldset><fieldset><legend>05 <span>Additional information</span></legend><label>Additional project requirements<textarea name="Additional requirements" rows="4"></textarea></label></fieldset><button class="btn gold-btn" type="submit">Prepare project enquiry →</button><p class="form-feedback" role="status"></p></form></div></section>'''
paths.append(render('/request-a-quote/','Request a Construction Quote','Prepare your construction project enquiry for Strategic Construction Group in Cape Town.',quote))
for slug,title,txt in [('privacy-policy','Privacy Policy','This is editable draft content for legal review before publication. The business must identify the information it collects, the purpose and lawful basis for processing, retention periods, service providers, security practices, data subject rights and contact details. The contact and quote forms on this site do not currently transmit information.'),('terms-and-conditions','Terms and Conditions','This is editable draft content for legal review before publication. The business must define the terms for use of this website, intellectual property, limitations of liability, external links, applicable law and contact details. Website content is informational and does not constitute a construction quotation or agreement.')]:
 body=banner(title,'Draft content — legal review required before publication.','cape-town.jpg','LEGAL')+f'<section class="section wrap narrow"><p class="notice"><b>Important:</b> This page is a placeholder, not a final legal policy.</p><h2>{title}</h2><p>{txt}</p></section>'
 paths.append(render('/'+slug+'/',title,'Draft '+title+' for review.',body))
# Cloudflare Pages serves this for missing routes.
notfound=banner('Page not found.','We could not find the page you were looking for.','cape-town.jpg','404')+'<section class="section wrap"><a class="btn dark-btn" href="/">Return to home →</a></section>'
render('/404/','Page Not Found','The requested page could not be found.',notfound)
(ROOT/'404.html').write_text((ROOT/'404/index.html').read_text().replace('<meta name="description"','<meta name="robots" content="noindex"><meta name="description"'))
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+base+'/sitemap.xml\n')
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+base+p+'</loc></url>' for p in paths)+'</urlset>')
